import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { 
  Search, 
  Filter, 
  Edit, 
  Trash2, 
  Save, 
  X, 
  Plus,
  FileText,
  Calendar,
  DollarSign,
  Target,
  Users
} from 'lucide-react';
import { 
  getInitiatives, 
  updateInitiative, 
  deleteInitiative,
  getDepartments 
} from '../lib/database';
import { formatCurrencyDisplay } from '../lib/currency';
import { useToast } from '../hooks/use-toast';

const STATUS_COLORS = {
  'مكتملة': 'bg-green-100 text-green-800',
  'قيد التنفيذ': 'bg-yellow-100 text-yellow-800',
  'متأخرة': 'bg-red-100 text-red-800',
  'لم تبدأ': 'bg-gray-100 text-gray-800'
};

const PRIORITY_COLORS = {
  'عالية': 'bg-red-100 text-red-800',
  'متوسطة': 'bg-yellow-100 text-yellow-800',
  'منخفضة': 'bg-green-100 text-green-800'
};

function DetailsTab({ statistics, onDataUpdate }) {
  const { toast } = useToast();
  const [initiatives, setInitiatives] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [filteredInitiatives, setFilteredInitiatives] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('الكل');
  const [departmentFilter, setDepartmentFilter] = useState('الكل');
  const [priorityFilter, setPriorityFilter] = useState('الكل');
  const [completionFilter, setCompletionFilter] = useState('الكل');
  const [editingId, setEditingId] = useState(null);
  const [editData, setEditData] = useState({});
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    loadData();
  }, []);

  useEffect(() => {
    filterInitiatives();
  }, [initiatives, searchTerm, statusFilter, departmentFilter, priorityFilter, completionFilter]);

  const loadData = async () => {
    try {
      setIsLoading(true);
      const [initiativesData, departmentsData] = await Promise.all([
        getInitiatives(),
        getDepartments()
      ]);
      setInitiatives(initiativesData);
      setDepartments(departmentsData);
    } catch (error) {
      console.error('Error loading data:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في تحميل البيانات",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  const filterInitiatives = () => {
    let filtered = [...initiatives];

    // Search filter
    if (searchTerm) {
      filtered = filtered.filter(initiative =>
        initiative.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        initiative.description?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        initiative.responsible_person?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        initiative.department?.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    // Status filter
    if (statusFilter !== 'الكل') {
      filtered = filtered.filter(initiative => initiative.status === statusFilter);
    }

    // Department filter
    if (departmentFilter !== 'الكل') {
      filtered = filtered.filter(initiative => initiative.department === departmentFilter);
    }

    // Priority filter
    if (priorityFilter !== 'الكل') {
      filtered = filtered.filter(initiative => initiative.priority === priorityFilter);
    }

    // Completion filter
    if (completionFilter !== 'الكل') {
      if (completionFilter === '0-25') {
        filtered = filtered.filter(initiative => initiative.completion_percentage >= 0 && initiative.completion_percentage <= 25);
      } else if (completionFilter === '26-50') {
        filtered = filtered.filter(initiative => initiative.completion_percentage >= 26 && initiative.completion_percentage <= 50);
      } else if (completionFilter === '51-75') {
        filtered = filtered.filter(initiative => initiative.completion_percentage >= 51 && initiative.completion_percentage <= 75);
      } else if (completionFilter === '76-100') {
        filtered = filtered.filter(initiative => initiative.completion_percentage >= 76 && initiative.completion_percentage <= 100);
      }
    }

    setFilteredInitiatives(filtered);
  };

  const handleEdit = (initiative) => {
    setEditingId(initiative.id);
    setEditData({ ...initiative });
  };

  const handleSave = async () => {
    try {
      await updateInitiative(editingId, editData);
      await loadData();
      onDataUpdate?.();
      setEditingId(null);
      setEditData({});
      toast({
        title: "تم الحفظ",
        description: "تم تحديث المبادرة بنجاح",
      });
    } catch (error) {
      console.error('Error updating initiative:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في تحديث المبادرة",
        variant: "destructive",
      });
    }
  };

  const handleCancel = () => {
    setEditingId(null);
    setEditData({});
  };

  const handleDelete = async (id) => {
    if (!confirm('هل أنت متأكد من حذف هذه المبادرة؟')) return;
    
    try {
      await deleteInitiative(id);
      await loadData();
      onDataUpdate?.();
      toast({
        title: "تم الحذف",
        description: "تم حذف المبادرة بنجاح",
      });
    } catch (error) {
      console.error('Error deleting initiative:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في حذف المبادرة",
        variant: "destructive",
      });
    }
  };

  const clearFilters = () => {
    setSearchTerm('');
    setStatusFilter('الكل');
    setDepartmentFilter('الكل');
    setPriorityFilter('الكل');
    setCompletionFilter('الكل');
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-orange-600 mx-auto mb-4"></div>
          <p className="text-gray-600">جاري تحميل البيانات...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Search and Filters */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2" style={{color: 'var(--brand-orange)'}}>
            <Search className="h-5 w-5" />
            البحث والفلترة المتقدمة
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {/* Search Bar */}
            <div className="relative">
              <Search className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-4 w-4" />
              <Input
                placeholder="البحث في المبادرات (الاسم، الوصف، المسؤول، الإدارة)..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pr-10"
              />
            </div>

            {/* Filters */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">الحالة</label>
                <select
                  value={statusFilter}
                  onChange={(e) => setStatusFilter(e.target.value)}
                  className="w-full p-2 border border-gray-300 rounded-md text-sm"
                >
                  <option value="الكل">جميع الحالات</option>
                  <option value="مكتملة">مكتملة</option>
                  <option value="قيد التنفيذ">قيد التنفيذ</option>
                  <option value="متأخرة">متأخرة</option>
                  <option value="لم تبدأ">لم تبدأ</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">الإدارة</label>
                <select
                  value={departmentFilter}
                  onChange={(e) => setDepartmentFilter(e.target.value)}
                  className="w-full p-2 border border-gray-300 rounded-md text-sm"
                >
                  <option value="الكل">جميع الإدارات</option>
                  {departments.map(dept => (
                    <option key={dept.id} value={dept.name}>{dept.name}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">الأولوية</label>
                <select
                  value={priorityFilter}
                  onChange={(e) => setPriorityFilter(e.target.value)}
                  className="w-full p-2 border border-gray-300 rounded-md text-sm"
                >
                  <option value="الكل">جميع الأولويات</option>
                  <option value="عالية">عالية</option>
                  <option value="متوسطة">متوسطة</option>
                  <option value="منخفضة">منخفضة</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">نسبة الإكمال</label>
                <select
                  value={completionFilter}
                  onChange={(e) => setCompletionFilter(e.target.value)}
                  className="w-full p-2 border border-gray-300 rounded-md text-sm"
                >
                  <option value="الكل">جميع النسب</option>
                  <option value="0-25">0-25%</option>
                  <option value="26-50">26-50%</option>
                  <option value="51-75">51-75%</option>
                  <option value="76-100">76-100%</option>
                </select>
              </div>

              <div className="flex items-end">
                <Button 
                  onClick={clearFilters}
                  variant="outline"
                  className="w-full"
                >
                  <Filter className="h-4 w-4 mr-2" />
                  مسح الفلاتر
                </Button>
              </div>
            </div>

            {/* Results Summary */}
            <div className="flex items-center justify-between text-sm text-gray-600 bg-gray-50 p-3 rounded-md">
              <span>عرض {filteredInitiatives.length} من أصل {initiatives.length} مبادرة</span>
              {(searchTerm || statusFilter !== 'الكل' || departmentFilter !== 'الكل' || priorityFilter !== 'الكل' || completionFilter !== 'الكل') && (
                <Badge variant="outline" className="text-xs">
                  فلاتر نشطة
                </Badge>
              )}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Initiatives Table */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2" style={{color: 'var(--brand-orange)'}}>
            <FileText className="h-5 w-5" />
            تفاصيل المبادرات ({filteredInitiatives.length})
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto">
            <table className="w-full border-collapse">
              <thead>
                <tr className="border-b border-gray-200 bg-gray-50">
                  <th className="text-right p-3 font-medium text-gray-700">الرقم</th>
                  <th className="text-right p-3 font-medium text-gray-700">اسم المبادرة</th>
                  <th className="text-right p-3 font-medium text-gray-700">الإدارة</th>
                  <th className="text-right p-3 font-medium text-gray-700">المسؤول</th>
                  <th className="text-center p-3 font-medium text-gray-700">الحالة</th>
                  <th className="text-center p-3 font-medium text-gray-700">الأولوية</th>
                  <th className="text-center p-3 font-medium text-gray-700">نسبة الإكمال</th>
                  <th className="text-center p-3 font-medium text-gray-700">الميزانية المخططة</th>
                  <th className="text-center p-3 font-medium text-gray-700">الميزانية المستخدمة</th>
                  <th className="text-center p-3 font-medium text-gray-700">الإجراءات</th>
                </tr>
              </thead>
              <tbody>
                {filteredInitiatives.map((initiative, index) => (
                  <tr key={initiative.id} className="border-b border-gray-100 hover:bg-gray-50">
                    <td className="p-3 text-sm">{index + 1}</td>
                    <td className="p-3">
                      {editingId === initiative.id ? (
                        <Input
                          value={editData.name || ''}
                          onChange={(e) => setEditData({...editData, name: e.target.value})}
                          className="text-sm"
                        />
                      ) : (
                        <div>
                          <div className="font-medium text-sm">{initiative.name}</div>
                          {initiative.description && (
                            <div className="text-xs text-gray-500 mt-1 line-clamp-2">
                              {initiative.description}
                            </div>
                          )}
                        </div>
                      )}
                    </td>
                    <td className="p-3 text-sm">
                      {editingId === initiative.id ? (
                        <select
                          value={editData.department || ''}
                          onChange={(e) => setEditData({...editData, department: e.target.value})}
                          className="w-full p-1 border border-gray-300 rounded text-sm"
                        >
                          <option value="">اختر الإدارة</option>
                          {departments.map(dept => (
                            <option key={dept.id} value={dept.name}>{dept.name}</option>
                          ))}
                        </select>
                      ) : (
                        initiative.department
                      )}
                    </td>
                    <td className="p-3 text-sm">
                      {editingId === initiative.id ? (
                        <Input
                          value={editData.responsible_person || ''}
                          onChange={(e) => setEditData({...editData, responsible_person: e.target.value})}
                          className="text-sm"
                        />
                      ) : (
                        initiative.responsible_person
                      )}
                    </td>
                    <td className="p-3 text-center">
                      {editingId === initiative.id ? (
                        <select
                          value={editData.status || ''}
                          onChange={(e) => setEditData({...editData, status: e.target.value})}
                          className="w-full p-1 border border-gray-300 rounded text-sm"
                        >
                          <option value="مكتملة">مكتملة</option>
                          <option value="قيد التنفيذ">قيد التنفيذ</option>
                          <option value="متأخرة">متأخرة</option>
                          <option value="لم تبدأ">لم تبدأ</option>
                        </select>
                      ) : (
                        <Badge className={`text-xs ${STATUS_COLORS[initiative.status] || 'bg-gray-100 text-gray-800'}`}>
                          {initiative.status}
                        </Badge>
                      )}
                    </td>
                    <td className="p-3 text-center">
                      {editingId === initiative.id ? (
                        <select
                          value={editData.priority || ''}
                          onChange={(e) => setEditData({...editData, priority: e.target.value})}
                          className="w-full p-1 border border-gray-300 rounded text-sm"
                        >
                          <option value="عالية">عالية</option>
                          <option value="متوسطة">متوسطة</option>
                          <option value="منخفضة">منخفضة</option>
                        </select>
                      ) : (
                        <Badge className={`text-xs ${PRIORITY_COLORS[initiative.priority] || 'bg-gray-100 text-gray-800'}`}>
                          {initiative.priority}
                        </Badge>
                      )}
                    </td>
                    <td className="p-3 text-center">
                      {editingId === initiative.id ? (
                        <Input
                          type="number"
                          min="0"
                          max="100"
                          value={editData.completion_percentage || 0}
                          onChange={(e) => setEditData({...editData, completion_percentage: parseInt(e.target.value) || 0})}
                          className="text-sm w-20"
                        />
                      ) : (
                        <div className="flex items-center justify-center">
                          <div className="w-16 bg-gray-200 rounded-full h-2 mr-2">
                            <div 
                              className="bg-blue-600 h-2 rounded-full" 
                              style={{width: `${initiative.completion_percentage || 0}%`}}
                            ></div>
                          </div>
                          <span className="text-sm font-medium">{initiative.completion_percentage || 0}%</span>
                        </div>
                      )}
                    </td>
                    <td className="p-3 text-center text-sm">
                      {editingId === initiative.id ? (
                        <Input
                          type="number"
                          value={editData.planned_budget || 0}
                          onChange={(e) => setEditData({...editData, planned_budget: parseFloat(e.target.value) || 0})}
                          className="text-sm w-24"
                        />
                      ) : (
                        formatCurrencyDisplay(initiative.planned_budget || 0)
                      )}
                    </td>
                    <td className="p-3 text-center text-sm">
                      {editingId === initiative.id ? (
                        <Input
                          type="number"
                          value={editData.used_budget || 0}
                          onChange={(e) => setEditData({...editData, used_budget: parseFloat(e.target.value) || 0})}
                          className="text-sm w-24"
                        />
                      ) : (
                        formatCurrencyDisplay(initiative.used_budget || 0)
                      )}
                    </td>
                    <td className="p-3 text-center">
                      {editingId === initiative.id ? (
                        <div className="flex items-center justify-center gap-1">
                          <Button
                            size="sm"
                            onClick={handleSave}
                            className="h-8 w-8 p-0"
                            style={{backgroundColor: 'var(--brand-orange)'}}
                          >
                            <Save className="h-3 w-3" />
                          </Button>
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={handleCancel}
                            className="h-8 w-8 p-0"
                          >
                            <X className="h-3 w-3" />
                          </Button>
                        </div>
                      ) : (
                        <div className="flex items-center justify-center gap-1">
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => handleEdit(initiative)}
                            className="h-8 w-8 p-0"
                          >
                            <Edit className="h-3 w-3" />
                          </Button>
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => handleDelete(initiative.id)}
                            className="h-8 w-8 p-0 text-red-600 hover:text-red-700"
                          >
                            <Trash2 className="h-3 w-3" />
                          </Button>
                        </div>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>

            {filteredInitiatives.length === 0 && (
              <div className="text-center py-8">
                <FileText className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                <p className="text-gray-500">لا توجد مبادرات تطابق معايير البحث</p>
                {(searchTerm || statusFilter !== 'الكل' || departmentFilter !== 'الكل') && (
                  <Button 
                    onClick={clearFilters}
                    variant="outline"
                    className="mt-2"
                  >
                    مسح الفلاتر
                  </Button>
                )}
              </div>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Summary Statistics */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center gap-2 mb-2">
              <Target className="h-4 w-4" style={{color: 'var(--brand-orange)'}} />
              <span className="text-sm font-medium text-gray-600">إجمالي المبادرات</span>
            </div>
            <div className="text-2xl font-bold" style={{color: 'var(--brand-orange)'}}>{filteredInitiatives.length}</div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-4">
            <div className="flex items-center gap-2 mb-2">
              <Calendar className="h-4 w-4 text-green-600" />
              <span className="text-sm font-medium text-gray-600">مكتملة</span>
            </div>
            <div className="text-2xl font-bold text-green-600">
              {filteredInitiatives.filter(i => i.status === 'مكتملة').length}
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-4">
            <div className="flex items-center gap-2 mb-2">
              <Users className="h-4 w-4 text-yellow-600" />
              <span className="text-sm font-medium text-gray-600">قيد التنفيذ</span>
            </div>
            <div className="text-2xl font-bold text-yellow-600">
              {filteredInitiatives.filter(i => i.status === 'قيد التنفيذ').length}
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-4">
            <div className="flex items-center gap-2 mb-2">
              <DollarSign className="h-4 w-4 text-blue-600" />
              <span className="text-sm font-medium text-gray-600">إجمالي الميزانية</span>
            </div>
            <div className="text-lg font-bold text-blue-600">
              {formatCurrencyDisplay(filteredInitiatives.reduce((sum, i) => sum + (i.planned_budget || 0), 0))}
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

export default DetailsTab;
